import java.io.*; import java.util.*; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int N = Integer.parseInt(st.nextToken()); int M = Integer.parseInt(st.nextToken()); int K = Integer.parseInt(st.nextToken()); int C = Integer.parseInt(st.nextToken()); List<List<Integer>> adj = new ArrayList<>(N + 1); for (int i = 0; i <= N; i++) adj.add(new ArrayList<>()); for (int i = 0; i < M; i++) { st = new StringTokenizer(br.readLine()); int u = Integer.parseInt(st.nextToken()); int v = Integer.parseInt(st.nextToken()); adj.get(u).add(v); adj.get(v).add(u); } int[] dist = new int[N + 1]; Arrays.fill(dist, -1); Queue<Integer> q = new LinkedList<>(); q.add(C); dist[C] = 0; int count = 0; while (!q.isEmpty()) { int curr = q.poll(); if (dist[curr] <= K) { count++; } if (dist[curr] < K) { for (int neighbor : adj.get(curr)) { if (dist[neighbor] == -1) { dist[neighbor] = dist[curr] + 1; q.add(neighbor); } } } } System.out.println(count); } }